//! Player scores shared between the match threads of the Pixel Arena server.

use std::collections::HashMap;
use std::sync::{Arc, Mutex};

pub type PlayerId = u32;

#[derive(Default)]
struct State {
    players: HashMap<PlayerId, i64>,
    total: i64,
}

/// Clones share the same scores, so each match thread keeps its own handle.
#[derive(Clone, Default)]
pub struct Board {
    // One lock makes each operation atomic, including changes to the total.
    state: Arc<Mutex<State>>,
}

impl Board {
    pub fn new() -> Self {
        Self::default()
    }

    /// Sets a player's score, replacing any previous score for that player.
    pub fn join(&self, id: PlayerId, score: i64) {
        let mut state = self.state.lock().unwrap();
        let previous = state.players.get(&id).copied().unwrap_or(0);
        // Widen the intermediate arithmetic so replacement cannot spuriously
        // overflow when the resulting total still fits in i64.
        let total = i64::try_from(state.total as i128 - previous as i128 + score as i128)
            .expect("board total overflow");
        state.players.insert(id, score);
        state.total = total;
    }

    /// Adds points to a player and to the board total.
    pub fn award(&self, id: PlayerId, points: i64) {
        let mut state = self.state.lock().unwrap();
        let score = state.players[&id] + points;
        let total = state.total + points;
        state.players.insert(id, score);
        state.total = total;
    }

    /// Moves points between two players. The board total does not change.
    /// Moving points from a player to the same player changes nothing.
    pub fn transfer(&self, from: PlayerId, to: PlayerId, points: i64) {
        if from == to {
            return;
        }
        let mut state = self.state.lock().unwrap();
        let from_score = state.players[&from] - points;
        let to_score = state.players[&to] + points;
        state.players.insert(from, from_score);
        state.players.insert(to, to_score);
    }

    pub fn score(&self, id: PlayerId) -> i64 {
        self.state.lock().unwrap().players[&id]
    }

    pub fn total(&self) -> i64 {
        self.state.lock().unwrap().total
    }
}

